Web Audio JS Snippet:
function playSwitchClick(ctx) {
  const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'triangle'; o.frequency.setValueAtTime(1200, t);
  o.frequency.exponentialRampToValueAtTime(180, t + 0.009);
  g.gain.setValueAtTime(0.04, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.01);
  o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.011);
}

function playBubblePop(ctx) {
  const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'sine'; o.frequency.setValueAtTime(340, t);
  o.frequency.exponentialRampToValueAtTime(680, t + 0.025);
  g.gain.setValueAtTime(0.05, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.028);
  o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.03);
}

let step = 0, last = 0;
function playComboPop(ctx) {
  const now = performance.now();
  step = (now - last < 2000) ? Math.min(step + 1, 12) : 0; last = now;
  const f = 320 * Math.pow(2, step / 12), t = ctx.currentTime;
  const o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'sine'; o.frequency.setValueAtTime(f, t);
  o.frequency.exponentialRampToValueAtTime(f * 1.35, t + 0.025);
  g.gain.setValueAtTime(0.06, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.03);
  o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.032);
}

function playDetentTick(ctx) {
  const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'triangle'; o.frequency.setValueAtTime(1600, t);
  o.frequency.exponentialRampToValueAtTime(220, t + 0.006);
  g.gain.setValueAtTime(0.03, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.007);
  o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.008);
}

function playDropThud(ctx) {
  const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'sine'; o.frequency.setValueAtTime(220, t);
  o.frequency.exponentialRampToValueAtTime(65, t + 0.04);
  g.gain.setValueAtTime(0.07, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.045);
  o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.048);
}

function playErrorReject(ctx) {
  [0, 0.07].forEach(offset => {
    const t = ctx.currentTime + offset, o = ctx.createOscillator(), g = ctx.createGain(), f = ctx.createBiquadFilter();
    o.type = 'sawtooth'; o.frequency.setValueAtTime(150, t); o.frequency.linearRampToValueAtTime(125, t + 0.05);
    f.type = 'lowpass'; f.frequency.setValueAtTime(420, t);
    g.gain.setValueAtTime(0.05, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.055);
    o.connect(f).connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.06);
  });
}

function playHeroChime(ctx) {
  [523.25, 659.25, 783.99].forEach((freq, i) => {
    const t = ctx.currentTime + i * 0.065, o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'sine'; o.frequency.setValueAtTime(freq, t);
    g.gain.setValueAtTime(0.05, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.38);
    o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.4);
  });
}

function startChargeRiser(ctx, durationSec = 0.8) {
  const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'sine'; o.frequency.setValueAtTime(220, t);
  o.frequency.exponentialRampToValueAtTime(660, t + durationSec);
  g.gain.setValueAtTime(0.001, t); g.gain.linearRampToValueAtTime(0.04, t + durationSec);
  o.connect(g).connect(ctx.destination); o.start(t);
  return () => { g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.04); o.stop(ctx.currentTime + 0.045); };
}

function playGlassyPing(ctx) {
  const t = ctx.currentTime;
  [[660, 0.04], [1320, 0.015]].forEach(([f, vol]) => {
    const o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'sine'; o.frequency.setValueAtTime(f, t);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.32);
    o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.34);
  });
}

function playKeycapThunk(ctx) {
  const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
  o.type = 'triangle'; o.frequency.setValueAtTime(380, t);
  o.frequency.exponentialRampToValueAtTime(95, t + 0.014);
  g.gain.setValueAtTime(0.045, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.015);
  o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.016);
}

function playCopySnip(ctx) {
  [[0, 1800, 600], [0.014, 2200, 900]].forEach(([off, f1, f2]) => {
    const t = ctx.currentTime + off, o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'triangle'; o.frequency.setValueAtTime(f1, t); o.frequency.exponentialRampToValueAtTime(f2, t + 0.008);
    g.gain.setValueAtTime(0.035, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.01);
    o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.011);
  });
}
